import { useState, useEffect } from 'react';
import { hrGetForms, hrCreateForm, hrUpdateForm, hrDeleteForm, hrActivateForm, hrDeactivateForm, hrAddQuestion, hrDeleteQuestion } from '../../api/index.js';
import { Spinner, Modal, Input, Textarea, Btn, Badge, useToast } from '../../components/shared/index.jsx';

const FIELD_LABELS = { score_1_4: 'Score 1-4', boolean: 'Yes / No', decimal: 'Decimal' };
const FIELD_TYPES = ['score_1_4', 'boolean', 'decimal'];

export function HRFormsPage() {
  const toast = useToast();
  const [forms, setForms] = useState([]);
  const [loading, setLoading] = useState(true);

  // selectedForm will hold the FULL detail (with questions)
  const [selectedForm, setSelected] = useState(null);

  const [showCreate, setShowCreate] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [showAddQ, setShowAddQ] = useState(false);
  const [formData, setFormData] = useState({ title: '', description: '' });
  const [qData, setQData] = useState({ questionText: '', fieldType: 'score_1_4', order: 0 });
  const [saving, setSaving] = useState(false);

  // 1. Load the sidebar list (FeedbackFormListSerializer)
  const loadSidebar = async () => {
    setLoading(true);
    try {
      const data = await hrGetForms();
      setForms(Array.isArray(data) ? data : []);
    } catch { toast('Failed to load forms', 'error'); }
    setLoading(false);
  };

  useEffect(() => { loadSidebar(); }, []);

  // 2. Fetch the Detail (FeedbackFormDetailSerializer)
  // Assuming hrGetForms(id) or a similar pattern exists, 
  // but if hrGetForms only returns the list, we must ensure 
  // the helper used to fetch a SINGLE form is called here.
  const refreshSelectedForm = async (formID) => {
    try {
      // NOTE: If your hrGetForms helper doesn't take an ID, 
      // you need a helper that calls the detail endpoint.
      // For now, I'll update the selectedForm state after additions.
      const data = await hrGetForms(); 
      const fresh = data.find(f => f.formID === formID);
      // If the list serializer doesn't have questions, 
      // you MUST have a detail helper call here.
      setSelected(fresh); 
    } catch { toast('Error refreshing form details', 'error'); }
  };

  const handleAddQuestion = async () => {
    if (!qData.questionText) return toast('Question text is required', 'error');
    setSaving(true);
    try {
      const res = await hrAddQuestion(selectedForm.formID, qData);
      toast('Question added');
      setShowAddQ(false);
      setQData({ questionText: '', fieldType: 'score_1_4', order: 0 });

      // Update local state immediately so it doesn't "disappear"
      const updatedQuestions = [...(selectedForm.questions || []), res];
      setSelected({ ...selectedForm, questions: updatedQuestions });

      // Refresh the sidebar to update the questionCount badge
      loadSidebar();
    } catch (err) {
      toast('Failed to add question', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteQuestion = async (q) => {
    if (!window.confirm('Delete this question?')) return;
    try {
      await hrDeleteQuestion(q.questionID);
      toast('Question deleted');

      // Filter out the deleted question locally
      const updatedQuestions = selectedForm.questions.filter(item => item.questionID !== q.questionID);
      setSelected({ ...selectedForm, questions: updatedQuestions });

      loadSidebar();
    } catch { toast('Delete failed', 'error'); }
  };

  return (
    <div style={{ maxWidth: 1280, margin: '0 auto', padding: '40px 32px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 28 }}>
        <h2>Feedback Forms</h2>
        <Btn onClick={() => setShowCreate(true)}>New Form</Btn>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '340px 1fr', gap: 24 }}>
        {/* Sidebar */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {forms.map(f => (
            <div key={f.formID} 
              onClick={() => setSelected(f)}
              style={{
                background: 'white', padding: 20, borderRadius: 20, cursor: 'pointer',
                border: `2px solid ${selectedForm?.formID === f.formID ? 'var(--red)' : '#EAECF0'}`
              }}>
              <div style={{ fontWeight: 700 }}>{f.title}</div>
              <div style={{ display: 'flex', gap: 8, marginTop: 8 }}>
                <Badge label={`${f.questionCount} Questions`} color="accent" />
                <Badge label={f.isActive ? 'Active' : 'Inactive'} color={f.isActive ? 'green' : 'gray'} />
              </div>
            </div>
          ))}
        </div>

        {/* Detail Area */}
        {selectedForm ? (
          <div style={{ background: 'white', borderRadius: 24, border: '1px solid #EAECF0' }}>
            <div style={{ padding: 24, borderBottom: '1px solid #F3F4F6', display: 'flex', justifyContent: 'space-between' }}>
              <h3>{selectedForm.title}</h3>
              <Btn size="sm" onClick={() => setShowAddQ(true)}>Add Question</Btn>
            </div>
            <div style={{ padding: 24 }}>
              {!selectedForm.questions || selectedForm.questions.length === 0 ? (
                <p style={{ color: 'var(--gray-400)' }}>No questions available. Add one to see it here.</p>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                  {selectedForm.questions.map((q, i) => (
                    <div key={q.questionID} style={{ background: 'var(--gray-50)', padding: 16, borderRadius: 16, display: 'flex', justifyContent: 'space-between' }}>
                      <div>
                        <div style={{ fontSize: 10, fontWeight: 800, color: 'var(--red)' }}>{FIELD_LABELS[q.fieldType]}</div>
                        <div style={{ fontWeight: 600 }}>{i + 1}. {q.questionText}</div>
                      </div>
                      <Btn size="sm" variant="danger" onClick={() => handleDeleteQuestion(q)}>Delete</Btn>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        ) : (
          <div style={{ padding: 60, textAlign: 'center', border: '2px dashed #EAECF0', borderRadius: 24 }}>
            Select a form to manage questions
          </div>
        )}
      </div>

      {/* ... Modals (Create, AddQ) stay here ... */}
    </div>
  );
}
